    --header "Accept: application/json" \
    --form "category=bug"\
    --form "subject=n"\
    --form "message=g"\
    --form "reproducibility=always"\
    --form "steps_to_reproduce=m"\
    --form "attachments[]=@/tmp/phpmglgb7msvlos5kiN9np" </code></pre></div>


