<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://127.0.0.1:8000/api/workspaces/1"
);

const headers = {
    "Authorization": "Bearer {VOTRE_TOKEN_SANCTUM}",
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('nom', 'b');
body.append('description', 'Et animi quos velit et fugiat.');
body.append('is_active', '');
body.append('remove_logo', '');
body.append('settings', '["architecto","architecto"]');
body.append('settings_array[language]', 'en');
body.append('settings_array[timezone]', 'Asia/Yekaterinburg');
body.append('settings_array[visibility]', 'public');
body.append('settings_array[default_project_visibility]', 'public');
body.append('settings_array[members_can_create_projects]', '');
body.append('settings_array[members_can_invite]', '1');
body.append('settings_array[members_can_delete_projects]', '1');
body.append('settings_array[require_task_validation]', '1');
body.append('settings_array[require_approval_for_time_off]', '');
body.append('settings_array[notify_on_new_member]', '');
body.append('settings_array[notify_on_new_project]', '');
body.append('settings_array[notify_on_task_assigned]', '');
body.append('settings_array[notify_on_deadline_approaching]', '');
body.append('settings_array[weekly_digest]', '1');
body.append('logo', document.querySelector('input[name="logo"]').files[0]);

fetch(url, {
    method: "PUT",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>


