<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://127.0.0.1:8000/api/taches/1"
);

const headers = {
    "Authorization": "Bearer {VOTRE_TOKEN_SANCTUM}",
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('titre', 'b');
body.append('description', 'Eius et animi quos velit et.');
body.append('objectif', 'architecto');
body.append('indicateurs_resultats', 'architecto');
body.append('statut', 'en_cours');
body.append('priorite', 'elevee');
body.append('echeance', '2026-06-04');
body.append('date_debut', '2026-06-04');
body.append('date_fin_reelle', '2026-06-04');
body.append('taux_realisation', '16');
body.append('estimated_hours', '17');
body.append('actual_hours', '15');
body.append('couleur', '#fEEeDb');
body.append('commentaire', 'architecto');
body.append('visibility', 'public');
body.append('validation_n1_required', '1');
body.append('validation_n2_required', '');
body.append('external_links', '["architecto","architecto"]');
body.append('uploaded_files[]', document.querySelector('input[name="uploaded_files[]"]').files[0]);
body.append('cover_image', document.querySelector('input[name="cover_image"]').files[0]);

fetch(url, {
    method: "PUT",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>


